let pages = [
  { id: 1, keys: [12, 24, 38] }
];
let splitCount = 0;
const MAX_KEYS = 5;

function renderBTreeVisuals() {
  const container = document.getElementById('pages-container');
  container.innerHTML = '';

  pages.forEach((page, idx) => {
    const pageDiv = document.createElement('div');
    const isFull = page.keys.length >= MAX_KEYS;
    pageDiv.className = `p-2.5 rounded-lg border font-mono text-xs flex flex-col gap-1 transition-all ${
      isFull ? 'bg-amber-950/80 border-amber-600' : 'bg-stone-900 border-stone-700'
    }`;
    pageDiv.id = `page-node-${page.id}`;

    const header = document.createElement('div');
    header.className = 'flex items-center justify-between text-[10px] text-stone-400 font-bold border-b border-stone-800 pb-1';
    header.innerHTML = `<span>Page #${page.id} (16KB)</span> <span>${page.keys.length}/${MAX_KEYS}</span>`;
    pageDiv.appendChild(header);

    const keysRow = document.createElement('div');
    keysRow.className = 'flex items-center gap-1 my-1';
    page.keys.forEach(k => {
      const kBadge = document.createElement('span');
      kBadge.className = 'px-1.5 py-0.5 rounded bg-stone-800 border border-stone-600 text-amber-300 font-bold text-[11px]';
      kBadge.textContent = k;
      kBadge.id = `key-badge-${k}`;
      keysRow.appendChild(kBadge);
    });
    pageDiv.appendChild(keysRow);

    if (idx < pages.length - 1) {
      const linkIndicator = document.createElement('div');
      linkIndicator.className = 'text-[9px] text-emerald-400 font-mono text-right';
      linkIndicator.textContent = 'next_page ➔';
      pageDiv.appendChild(linkIndicator);
    }
    container.appendChild(pageDiv);
  });

  // Telemetry
  document.getElementById('tel-page-count').textContent = `${pages.length} Pages`;
  document.getElementById('tel-split-count').textContent = `${splitCount} Splits`;
  const totalKeys = pages.reduce((acc, p) => acc + p.keys.length, 0);
  const maxCapacity = pages.length * MAX_KEYS;
  const fillPct = Math.round((totalKeys / maxCapacity) * 100);
  document.getElementById('tel-fill-pct').textContent = `${fillPct}% Fill`;
}

function insertRecord() {
  const newKey = Math.floor(Math.random() * 85) + 10;
  const log = document.getElementById('btree-log');

  // Find target page
  let target = pages[0];
  for (let p of pages) {
    if (p.keys.length > 0 && newKey <= p.keys[p.keys.length - 1]) {
      target = p;
      break;
    }
    target = p;
  }

  if (target.keys.includes(newKey)) {
    log.innerHTML = `<span class="text-stone-400">Key ${newKey} already exists in Page #${target.id}. Skipped.</span>`;
    return;
  }

  target.keys.push(newKey);
  target.keys.sort((a, b) => a - b);

  if (target.keys.length > MAX_KEYS) {
    // Trigger 50/50 page split
    splitCount++;
    const mid = Math.floor(target.keys.length / 2);
    const leftKeys = target.keys.slice(0, mid);
    const rightKeys = target.keys.slice(mid);

    target.keys = leftKeys;
    const newPageId = pages.length + 1;
    const newPage = { id: newPageId, keys: rightKeys };

    const targetIdx = pages.indexOf(target);
    pages.splice(targetIdx + 1, 0, newPage);

    log.innerHTML = `<span class="text-rose-400 font-bold">[PAGE SPLIT]</span> Page #${target.id} filled! Allocated new 16KB Page #${newPageId}. 50% of keys moved. Parent routing pointer updated!`;
  } else {
    log.innerHTML = `<span class="text-emerald-400">[INSERT]</span> Inserted key <strong>${newKey}</strong> into Page #${target.id}. Current capacity: ${target.keys.length}/${MAX_KEYS}.`;
  }

  renderBTreeVisuals();
}

function performRangeScan() {
  const log = document.getElementById('btree-log');
  const minK = 20;
  const maxK = 60;

  log.innerHTML = `<strong>[RANGE SCAN]</strong> <code>WHERE key BETWEEN ${minK} AND ${maxK}</code>...`;

  let visitedPages = 0;
  let matchedKeys = [];

  pages.forEach(p => {
    const matches = p.keys.filter(k => k >= minK && k <= maxK);
    if (matches.length > 0) {
      visitedPages++;
      matchedKeys.push(...matches);
      const node = document.getElementById(`page-node-${p.id}`);
      if (node) {
        node.classList.add('ring-2', 'ring-blue-400');
        setTimeout(() => node.classList.remove('ring-2', 'ring-blue-400'), 1200);
      }
    }
  });

  document.getElementById('tel-scan-cost').textContent = `${visitedPages} Pages (${matchedKeys.length} rows)`;
  log.innerHTML += `<br/><span class="text-blue-400 font-bold">[SEQUENTIAL READ]</span> Glided across ${visitedPages} contiguous leaf pages using next_page pointers. Found keys [${matchedKeys.join(', ')}]. Zero tree re-traversals!`;
}

function resetTreeSimulator() {
  pages = [{ id: 1, keys: [12, 24, 38] }];
  splitCount = 0;
  document.getElementById('tel-scan-cost').textContent = '--';
  document.getElementById('btree-log').innerHTML = 'Simulator reset to single initial leaf page.';
  renderBTreeVisuals();
}

renderBTreeVisuals();
